import {farmPlants} from './farm.js';
import {normalizeExpeditions,expeditionEnter,expeditionHash,expeditionPalette} from './expeditions.js';
import {normalizeTrailMachines,trailMachineJournal} from './trail-machines.js';

export const myWorldKinds={home:{name:'Home-world colony',icon:'🌳'},planet:{name:'Alien planet',icon:'🪐'},moon:{name:'Alien moon',icon:'🌙'}};
export const myWorldLandscapes={forest:'Forest',rocky:'Rocky hills',lake:'Lakeside'};
const myWorldClean=s=>typeof s==='string'?s.replace(/[\u0000-\u001f<>]/g,'').slice(0,24):'';
export function normalizeMyWorlds(raw={}){
 const r=raw&&typeof raw==='object'?raw:{},s={active:null,worlds:{},away:null,travel:null};
 for(const id of Object.keys(myWorldKinds)){const q=r.worlds?.[id]||{},seed=Number.isInteger(q.seed)?q.seed>>>0:expeditionHash(Number.isInteger(r.seed)?r.seed>>>0:2063,Object.keys(myWorldKinds).indexOf(id),221);s.worlds[id]={id,name:myWorldClean(q.name)||{home:'My Green Home',planet:'Star Garden',moon:'Moon Haven'}[id],landscape:Object.hasOwn(myWorldLandscapes,q.landscape)?q.landscape:id==='home'?'forest':'rocky',seed,created:q.created===true,visits:Math.max(0,Math.min(999999,Math.floor(q.visits)||0)),expeditions:normalizeExpeditions(q.expeditions||{seed}),trailMachines:normalizeTrailMachines(q.trailMachines)};}
 if(Object.hasOwn(myWorldKinds,r.active)&&s.worlds[r.active].created)s.active=r.active;
 if(r.away&&typeof r.away==='object')s.away={expeditions:normalizeExpeditions(r.away.expeditions),trailMachines:normalizeTrailMachines(r.away.trailMachines)};
 const t=r.travel;if(t&&['hub',...Object.keys(myWorldKinds)].includes(t.to)&&(t.to==='hub'||s.worlds[t.to].created))s.travel={to:t.to,offworld:t.offworld===true,phase:Math.max(0,Math.min(5,Math.floor(t.phase)||0)),time:Math.max(0,Math.min(2,Number(t.time)||0)),start:{x:Math.max(80,Math.min(920,Number(t.start?.x)||500)),y:Math.max(180,Math.min(460,Number(t.start?.y)||350))}};
 return s;
}
export function myWorldBind(host){const s=host.myWorlds,w=s.worlds[s.active];if(!w)return;host.expeditions=w.expeditions;host.trailMachines=w.trailMachines;host.expeditions.active='farm';host.expeditions.colony={id:w.id,kind:w.id,name:w.name,landscape:w.landscape};host.expeditions.worlds.farm.colony=host.expeditions.colony;}
export function myWorldCapture(host){const w=host.myWorlds.worlds[host.myWorlds.active];if(w){w.expeditions=host.expeditions;w.trailMachines=host.trailMachines;}}
export function myWorldRestore(host){if(host.myWorlds.active)myWorldBind(host);}
export function myWorldLeave(host){myWorldCapture(host);const s=host.myWorlds;if(!s.active)return;const away=s.away;s.active=null;s.away=null;if(away){host.expeditions=away.expeditions;host.trailMachines=away.trailMachines;}else{host.expeditions=normalizeExpeditions();host.trailMachines=normalizeTrailMachines();}}
export function myWorldArrive(host,id){
 const s=host.myWorlds;if(id==='hub'){myWorldLeave(host);s.travel=null;return {hub:true};}
 const world=s.worlds[id];if(!world||!world.created){s.travel=null;return {};}
 if(s.active===id){s.travel=null;return {arrived:id};}
 myWorldCapture(host);if(!s.active)s.away={expeditions:host.expeditions,trailMachines:host.trailMachines};s.active=id;myWorldBind(host);
 // Only actual arrival from elsewhere advances one watered growth stage. Reload never does.
 world.expeditions.active=null;expeditionEnter(world.expeditions,'farm');world.visits++;s.travel=null;return {arrived:id};
}
export function beginMyWorldTravel(host,to,start={x:500,y:350}){const s=host.myWorlds;if(!['hub',...Object.keys(myWorldKinds)].includes(to)||to!=='hub'&&!s.worlds[to].created)return false;host.trailMachines.roomOpen=null;s.travel={to,offworld:['planet','moon'].includes(to)||['planet','moon'].includes(s.active),phase:0,time:0,start:{x:Math.max(80,Math.min(920,start.x)),y:Math.max(180,Math.min(460,start.y))}};return true;}
const myWorldTripStages=['depart','form','launch','space','land','unfold'];
export function tickMyWorldTravel(host,dt,{paused=false,overlay=false,reduced=false,effects=true,skip=false}={}){
 const t=host.myWorlds.travel;if(!t||paused||overlay)return null;if(skip||reduced||!effects)return myWorldArrive(host,t.to);
 const stages=t.offworld?myWorldTripStages:['depart','land'];t.time+=Math.max(0,Math.min(.05,dt));if(t.time>=1.5){t.time=0;t.phase++;if(t.phase>=stages.length)return myWorldArrive(host,t.to);}return null;
}
export function myWorldTravelPose(s){const t=s.travel;if(!t)return null;const stages=t.offworld?myWorldTripStages:['depart','land'],stage=stages[Math.min(t.phase,stages.length-1)],u=Math.max(0,Math.min(1,t.time/1.5)),smooth=u*u*(3-2*u),target=t.to==='hub'?'home':t.to;let astronaut={x:500,y:380,scale:1},pip={x:440,y:330,scale:1},rocket={x:500,y:300,scale:0,angle:0};
 if(stage==='depart'){astronaut={x:t.offworld?t.start.x+(430-t.start.x)*smooth:t.start.x+1100*smooth,y:t.offworld?t.start.y+(330-t.start.y)*smooth:t.start.y-100*smooth,scale:1};pip=t.offworld?{x:t.start.x-65+(565-(t.start.x-65))*smooth,y:t.start.y-45+(315-(t.start.y-45))*smooth,scale:1}:{x:astronaut.x-65,y:astronaut.y-45,scale:1};}
 if(stage==='form'){astronaut={x:500-70*(1-smooth),y:330,scale:1-smooth};pip={x:500+65*(1-smooth),y:315,scale:1-smooth};rocket={x:500,y:290,scale:smooth,angle:0};}
 if(stage==='launch'){astronaut.scale=pip.scale=0;rocket={x:500,y:380-660*smooth,scale:1,angle:0};}
 if(stage==='space'){astronaut.scale=pip.scale=0;rocket={x:150+650*smooth,y:270-60*smooth,scale:.7,angle:90};}
 if(stage==='land'){if(t.offworld){astronaut.scale=pip.scale=0;rocket={x:500,y:-180+560*smooth,scale:1,angle:0};}else{astronaut={x:1150-650*smooth,y:380-40*(1-smooth),scale:1};pip={x:astronaut.x-65,y:astronaut.y-45,scale:1};}}
 if(stage==='unfold'){rocket={x:500,y:380,scale:1-smooth,angle:0};astronaut={x:500+30*smooth,y:395,scale:smooth};pip={x:440,y:345,scale:smooth};}
 return {stage,target,space:stage==='space',background:stage==='space'||['land','unfold'].includes(stage)?target:'home',astronaut,pip,rocket,caption:{depart:'J.A.C.C. and PIP are flying out!',form:'Together, we become our travel rocket!',launch:'Up through the sky!',space:'Across space to our world!',land:'A gentle landing.',unfold:'J.A.C.C. and PIP are ready to explore!'}[stage]};
}
export function myWorldAction(host,a){const s=host.myWorlds,w=s.worlds[a.id];let route=a.route||'home',travel=null,message='';if(a.type==='create'&&w){w.created=true;route='world:'+a.id;}if(a.type==='name'&&w){w.name=myWorldClean(a.value)||w.name;route='world:'+a.id;}if(a.type==='key'&&w){w.name=(a.value==='clear'?'':a.value==='delete'?[...w.name].slice(0,-1).join(''):w.name+(a.value==='space'?' ':/^[A-Z]$/.test(a.value)?a.value:'')).slice(0,24);route='letters:'+a.id+':'+(a.page||0);}if(a.type==='landscape'&&w&&Object.hasOwn(myWorldLandscapes,a.value)&&!w.visits){w.landscape=a.value;route='world:'+a.id;}if(a.type==='go'&&w?.created){w.name=myWorldClean(w.name).trim()||{home:'My Green Home',planet:'Star Garden',moon:'Moon Haven'}[a.id];travel=a.id;}if(a.type==='hub')travel='hub';if(s.active)myWorldBind(host);return {route,travel,message};}
const myWorldPage=(label,route)=>({label,type:'page',route});
export function myWorldView(s,route='home'){
 const [kind,id='',page='0']=route.split(':'),w=s.worlds[id],n=Math.max(0,Math.min(8,parseInt(page)||0)),back=myWorldPage('← My World','home'),v=(title,text,actions)=>({title,text,actions});
 if(kind==='home')return v('My World','Your own places to name, grow and build. Each destination keeps its own garden and machines.',[...Object.entries(myWorldKinds).map(([id,k])=>myWorldPage(k.icon+' '+s.worlds[id].name+(s.worlds[id].created?'':' / create'), 'world:'+id)),myWorldPage('🤖 PIP / one little goal','help'),{label:'🏠 Fly to Home Base',type:'hub'}]);
 if(kind==='world'&&w)return v(w.name,myWorldKinds[id].name+' · '+myWorldLandscapes[w.landscape]+'. '+(id==='home'?'A colony on our home world.':'A fictional world. Plants grow in supplied, protected growing beds; these are not known alien plants.'),[...(!w.created?[{label:'＋ Make this my world',type:'create',id}]:[{label:'🚀 Visit my world',type:'go',id}]),myWorldPage('✏ Name my world','name:'+id),...(!w.visits?[myWorldPage('🌄 Choose landscape','landscape:'+id)]:[]),back]);
 if(kind==='name'&&w)return v('Name: '+(w.name||'My World'),'Choose a name or use the untimed tap keyboard. Naming is optional.',[...['Star Garden','Moon Haven'].map(value=>({label:value,type:'name',id,value})),{label:'⌫ Clear my name',type:'key',value:'clear',id,page:0},myWorldPage('✏ My own letters','letters:'+id+':0'),myWorldPage('← My world','world:'+id)]);
 if(kind==='letters'&&w)return v('My world: '+(w.name||'…'),'Tap letters. Use Clear to start a new name. Nothing is timed.',[...[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ','space'].slice(n*3,n*3+3).map(value=>({label:value==='space'?'␣ Space':value,type:'key',value,id,page:n})),{label:'⌫ Remove last',type:'key',value:'delete',id,page:n},myWorldPage('More letters →','letters:'+id+':'+((n+1)%9)),myWorldPage('✓ Done','world:'+id)]);
 if(kind==='landscape'&&w)return v('My landscape','Choose before your first visit. This keeps later landscape changes from hiding your creations.',Object.entries(myWorldLandscapes).map(([value,name])=>({label:name,type:'landscape',id,value})).concat([myWorldPage('← My world','world:'+id)]));
 if(kind==='help')return v('PIP / Your own home','Try one little thing: place a habitat, plant an owned seed, or explore. Your creations wait here for you. You can skip every goal.',[...(s.active?[{label:'🏠 Place my habitat',type:'machines'},{label:'🌱 Plant one seed',type:'plant'}]:[back]),myWorldPage('🌍 My worlds','home'),{label:'▶ Keep exploring',type:'close'}]);
 return myWorldView(s,'home');
}
export const myWorldTileStyles=['rocky','lake','planet','moon'];
export const myWorldTileTypes=['grass','soil','farmsoil','rock','trunk','leaf','pond','flower'];
export const myWorldTileKeys=myWorldTileStyles.flatMap(style=>myWorldTileTypes.map(type=>style+'-'+type));
export function myWorldStyle(exp){const c=exp.colony;return !c?'':c.kind==='home'?c.landscape==='forest'?'':c.landscape:c.kind;}
export function myWorldTileColor(style,type){const colors={rocky:{grass:'#aca691',soil:'#8e8273',farmsoil:'#9c846b',rock:'#7e7e83',trunk:'#8d806a',leaf:'#7e9d73',pond:'#739aa8',flower:'#d5c47d'},lake:{grass:'#8ab6a0',soil:'#a28d70',farmsoil:'#927b61',rock:'#8c9198',trunk:'#82765f',leaf:'#68947b',pond:'#6eabc0',flower:'#c7b7dd'},planet:{grass:'#ac9cbf',soil:'#826c92',farmsoil:'#887489',rock:'#706485',trunk:'#9fa7b9',leaf:'#8fbec0',pond:'#6a9cad',flower:'#bcafde'},moon:{grass:'#aeb0bb',soil:'#828591',farmsoil:'#89816e',rock:'#707482',trunk:'#8c94a4',leaf:'#adb6c4',pond:'#749ba7',flower:'#d9c7a0'}};return colors[style]?.[type]||expeditionPalette[type];}
export function myWorldTileSvg(style,type){return `<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40"><rect width="40" height="40" fill="${myWorldTileColor(style,type)}"/><path d="M0 39h40M39 0v40" stroke="#17384a" stroke-opacity=".16"/>${type==='rock'?'<path d="M7 29l5-17 18-6 5 23z" fill="#d1ced2" opacity=".3"/>':''}</svg>`;}
export function myWorldRocketSvg(color='#cf4348'){return `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="160" viewBox="0 0 100 160"><path d="M30 100L5 137l25-8m40-29 25 37-25-8" fill="${color}" stroke="#17384a" stroke-width="3"/><path d="M28 130V48Q30 20 50 5 70 20 72 48v82z" fill="#c4ced8" stroke="#17384a" stroke-width="4"/><path d="M30 47Q35 20 50 8q15 12 20 39z" fill="${color}"/><rect x="38" y="58" width="24" height="25" rx="8" fill="#28495e" stroke="#35d3c9" stroke-width="4"/><path d="M36 92h28m-28 12h28" stroke="${color}" stroke-width="5"/><path d="M37 133l13 24 13-24" fill="#35d3c9"/></svg>`;}
export function myWorldBackdropSvg(kind='home',space=false){const sky=space?'#222d4b':kind==='moon'?'#293350':kind==='planet'?'#716b9e':'#9ccfdf',ground=kind==='moon'?'#a6a8b1':kind==='planet'?'#a38cba':'#92b27c';let s=`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600"><rect width="1000" height="600" fill="${sky}"/>`;if(space||kind==='moon')for(let i=0;i<34;i++)s+=`<rect x="${(i*233+37)%980}" y="${(i*97+31)%370}" width="3" height="3" fill="#e3e5d8"/>`;if(space)s+=`<circle cx="810" cy="390" r="140" fill="${ground}"/><path d="M710 358l100-70 105 110-40 75-140-20z" fill="#7b90ac"/>`;else s+=`<circle cx="815" cy="125" r="${kind==='moon'?62:35}" fill="${kind==='moon'?'#81a2b6':'#d5c6ac'}"/><path d="M0 480l190-95 180 60 200-115 220 110 210-50v210H0z" fill="${ground}"/><path d="M0 530l190-55 170 55 260-50 200 40 180-40v120H0z" fill="${kind==='moon'?'#898e9b':kind==='planet'?'#87779f':'#7e9e6c'}"/><rect x="415" y="470" width="170" height="18" fill="#c4ced8"/><path d="M435 478h130" stroke="#35d3c9" stroke-width="4"/>`;return s+'</svg>';}

export function myWorldJournal(s,section){const out=[];for(const w of Object.values(s.worlds)){if(!w.visits)continue;if(section==='adventures')out.push({id:'myworld-'+w.id,title:'My world: '+w.name,icon:myWorldKinds[w.id].icon,summary:'I visited my '+myWorldKinds[w.id].name.toLowerCase()+'.',fact:'My garden and creations wait here when I return.',target:'grounds-home',myWorldId:w.id});if(section==='experiments')for(const seed of w.expeditions.worlds.farm.harvested)out.push({id:'myworld-'+w.id+'-'+seed,title:'I grew '+(farmPlants.find(p=>p.id===seed)?.name||'a plant')+' on '+w.name,icon:'🌱',summary:'I planted, watered and returned to my own growing beds.',fact:'These are protected, supplied growing beds in a fictional colony.',target:'grounds-home',myWorldId:w.id});for(const e of trailMachineJournal(w.trailMachines,section))out.push({...e,id:'myworld-'+w.id+'-'+e.id,myWorldId:w.id});}return out;}

export function myWorldAstronautSvg(color){return `<svg xmlns="http://www.w3.org/2000/svg" width="60" height="80"><path d="M4 40h52m-42 8v20m32-20v20" stroke="#c4ced8" stroke-width="8"/><path d="M15 66l4 12 4-12m14 0 4 12 4-12" fill="#35d3c9"/><rect x="17" y="35" width="27" height="31" fill="${color}"/><rect x="12" y="7" width="37" height="31" rx="7" fill="#c4ced8"/><rect x="18" y="14" width="25" height="15" fill="#28495e"/></svg>`;}
